class Solution {
    public: int findMaxValueOfEquation(vector<vector<int>>& points,int k){
        deque<int> pending;
        int answer=INT_MIN;
        for(int j=0;j<(int)points.size();++j){
            while(!pending.empty()&&points[j][0]-points[pending.front()][0]>k)pending.pop_front();
            if(!pending.empty()){
                int i=pending.front();
                answer=max(answer,points[j][1]+points[j][0]+points[i][1]-points[i][0]);
            }
            int value=points[j][1]-points[j][0];
            while(!pending.empty()&&points[pending.back()][1]-points[pending.back()][0]<=value)pending.pop_back();
            pending.push_back(j);
        }
        return answer;
    }
};
